import React from 'react';
import { motion } from 'framer-motion';
import {
  MapPin, MessageCircle, Video, Image, Users,
  Shield, Bell, FileText, Eye, Phone, Check
} from 'lucide-react';
import { Reveal3D, TiltCard, ChapterHeading } from './motion-primitives';

const FeaturesSection = () => {
  const features = [
    { id: 1, icon: MapPin, title: 'Live Location Map', description: 'See where your friends are in real-time on a beautiful 3D map. Get notified when friends are nearby and never miss spontaneous meetups.', benefits: ['Real-time location sharing', 'Nearby friend alerts', 'Privacy controls'] },
    { id: 2, icon: MessageCircle, title: 'Smart Status Updates', description: 'Share your availability with real-time status. Auto-detect driving, meetings, or sleeping. Friends know when NOT to disturb you.', benefits: ['Auto-detect activities', 'Emergency override', 'Custom status messages'] },
    { id: 3, icon: Image, title: '24-Hour Stories', description: "Share photos, videos, and text that disappear in 24 hours. See who viewed your stories and engage with friends' moments.", benefits: ['Photo & video stories', 'View tracking', 'Privacy settings'] },
    { id: 4, icon: FileText, title: 'For You Feed', description: "See ONLY your friends' posts. No strangers, no algorithm chaos. Just real connections with people you care about.", benefits: ['Friends-only content', 'Like & comment', 'Share moments'] },
    { id: 5, icon: Eye, title: 'Explore Tab', description: 'Discover public posts from non-friends. Find trending content, connect with new people, and expand your network.', benefits: ['Public content discovery', 'Trending posts', 'New connections'] },
    { id: 6, icon: Video, title: 'Video & Voice Calls', description: 'Crystal clear video and voice calls with friends and groups. Screen sharing, background blur, and recording capabilities.', benefits: ['HD video calls', 'Group calling', 'Screen sharing'] },
    { id: 7, icon: Phone, title: 'Advanced Messaging', description: 'Text, voice notes, files, and more. Disappearing messages, read receipts, and smart notifications keep you connected.', benefits: ['Rich messaging', 'Voice notes', 'File sharing'] },
    { id: 8, icon: FileText, title: 'Pages & Communities', description: 'Create pages for businesses, events, or communities. Build followers, share content, and get verified badges.', benefits: ['Create pages', 'Verified badges', 'Analytics dashboard'] },
    { id: 9, icon: Users, title: 'Unified Friends System', description: 'Device contacts and app connections in one place. Seamlessly manage all your friendships and connections.', benefits: ['Device contact sync', 'App connections', 'Friend requests'] },
    { id: 10, icon: Bell, title: 'Smart Notifications', description: 'Context-aware notifications that adapt to your status. Important messages break through, casual ones wait.', benefits: ['Priority alerts', 'Do not disturb', 'Custom rules'] },
    { id: 11, icon: Shield, title: 'Privacy & Security', description: 'Complete control with ghost mode, timer mode, and custom visibility. Your data is encrypted and protected.', benefits: ['Ghost mode', 'Timer mode', 'End-to-end encryption'] }
  ];

  return (
    <section id="features" className="section-padding bg-white text-ink-900 relative overflow-hidden">
      <div className="orb orb-violet w-[500px] h-[500px] -top-40 -left-40 opacity-30"></div>
      <div className="orb orb-fuchsia w-[400px] h-[400px] -bottom-40 -right-40 opacity-20"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <ChapterHeading
          chapter="Chapter 04 — Features"
          title="Powerful Features for Modern Communication"
          subtitle="Discover how Syncup transforms the way you connect, coordinate, and communicate with others"
        />

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
          {features.map((feature, idx) => (
            <Reveal3D key={feature.id} delay={(idx % 3) * 0.12}>
              <TiltCard className="h-full">
                <div className="modern-card p-6 depth-shadow hover-lift h-full group">
                  <div className="scene-3d mb-4">
                    <motion.div
                      className="w-14 h-14 bg-gradient-to-br from-purple-500 to-purple-700 rounded-2xl flex items-center justify-center depth-shadow"
                      whileHover={{ rotateY: 180, rotateX: 8, scale: 1.08 }}
                      transition={{ type: 'spring', stiffness: 200, damping: 14 }}
                      style={{ transformStyle: 'preserve-3d' }}
                    >
                      <feature.icon className="w-7 h-7 text-white" />
                    </motion.div>
                  </div>
                  <h3 className="text-lg font-bold text-ink-900 mb-2 text-refined font-display">{feature.title}</h3>
                  <p className="text-ink-600 mb-4 leading-relaxed text-sm">{feature.description}</p>
                  <ul className="space-y-2">
                    {feature.benefits.map((benefit, index) => (
                      <motion.li
                        key={index}
                        className="flex items-center text-xs text-ink-600 font-medium"
                        initial={{ opacity: 0, x: -10 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: 0.3 + index * 0.1 }}
                      >
                        <Check className="w-3.5 h-3.5 text-purple-500 mr-2 flex-shrink-0" />
                        {benefit}
                      </motion.li>
                    ))}
                  </ul>
                </div>
              </TiltCard>
            </Reveal3D>
          ))}
        </div>
      </div>
    </section>
  );
};

export default FeaturesSection;
