import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  Clock, MessageCircle, Video, Coffee, Zap, Calendar
} from 'lucide-react';
import { ChapterHeading, TiltCard, Counter } from './motion-primitives';

const LiveDashboardDemo = () => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [activeUsers, setActiveUsers] = useState([]);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const users = [
      { id: 1, name: 'Sarah Chen', role: 'Product Manager', avatar: 'SC', status: 'at-airport', activity: 'Flight to NYC at 6 PM', lastSeen: 'now', statusColor: 'bg-purple-500', activityIcon: Clock, location: 'SFO Airport' },
      { id: 2, name: 'Mike Rodriguez', role: 'Developer', avatar: 'MR', status: 'driving', activity: 'Commuting home', lastSeen: '2 min ago', statusColor: 'bg-fuchsia-500', activityIcon: Clock, location: 'Highway 101' },
      { id: 3, name: 'Emma Wilson', role: 'Designer', avatar: 'EW', status: 'cinema', activity: 'Movie at 8 PM', lastSeen: '5 min ago', statusColor: 'bg-violet-500', activityIcon: Clock, location: 'AMC Theater' },
      { id: 4, name: 'Alex Park', role: 'Marketing', avatar: 'AP', status: 'shopping', activity: 'Mall visit until 7 PM', lastSeen: 'now', statusColor: 'bg-pink-500', activityIcon: Clock, location: 'Westfield Mall' },
      { id: 5, name: 'Lisa Zhang', role: 'Sales', avatar: 'LZ', status: 'vacation', activity: 'Beach vacation in Hawaii', lastSeen: '1 min ago', statusColor: 'bg-purple-400', activityIcon: Clock, location: 'Maui, Hawaii' },
      { id: 6, name: 'David Kim', role: 'DevOps', avatar: 'DK', status: 'friends', activity: 'Chilling with friends', lastSeen: '3 min ago', statusColor: 'bg-fuchsia-400', activityIcon: Coffee, location: 'Central Park' }
    ];

    const updateStatuses = () => {
      const updatedUsers = users.map(user => {
        const random = Math.random();
        if (random < 0.1) {
          const activities = [
            { activity: 'At airport - Flight delayed', status: 'at-airport', color: 'bg-purple-500', icon: Clock },
            { activity: 'Driving to cinema', status: 'driving', color: 'bg-fuchsia-500', icon: Clock },
            { activity: 'Movie night with family', status: 'cinema', color: 'bg-violet-500', icon: Clock },
            { activity: 'Shopping at mall', status: 'shopping', color: 'bg-pink-500', icon: Clock },
            { activity: 'On vacation in Bali', status: 'vacation', color: 'bg-purple-400', icon: Clock },
            { activity: 'Coffee with friends', status: 'friends', color: 'bg-fuchsia-400', icon: Coffee },
            { activity: 'Available for work', status: 'work-available', color: 'bg-emerald-500', icon: MessageCircle },
            { activity: 'In office meeting', status: 'work-meeting', color: 'bg-red-500', icon: Video }
          ];
          const newActivity = activities[Math.floor(Math.random() * activities.length)];
          return { ...user, activity: newActivity.activity, status: newActivity.status, statusColor: newActivity.color, activityIcon: newActivity.icon, lastSeen: 'now' };
        }
        return user;
      });
      setActiveUsers(updatedUsers);
    };

    setActiveUsers(users);
    const statusTimer = setInterval(updateStatuses, 3000);
    return () => clearInterval(statusTimer);
  }, []);

  const workAvailableCount = activeUsers.filter(user => user.status === 'work-available').length;
  const personalActivityCount = activeUsers.filter(user => ['at-airport', 'driving', 'cinema', 'shopping', 'vacation', 'friends'].includes(user.status)).length;
  const workMeetingCount = activeUsers.filter(user => user.status === 'work-meeting').length;

  return (
    <section className="section-padding bg-gradient-to-br from-purple-50 to-white text-ink-900 relative overflow-hidden">
      <div className="orb orb-purple w-[400px] h-[400px] top-10 -left-40 opacity-30"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <ChapterHeading
          chapter="Chapter 04 — Live View"
          title="Live Life Dashboard"
          subtitle="See your team's complete life status - work, travel, entertainment, and personal activities"
        />

        <div className="grid lg:grid-cols-3 gap-6 sm:gap-8">
          {/* Live Stats Panel */}
          <div className="lg:col-span-1">
            <TiltCard>
              <div className="modern-card p-5 sm:p-6 depth-shadow h-fit lg:sticky lg:top-8">
                <div className="text-center mb-5 sm:mb-6">
                  <div className="text-2xl font-bold text-ink-900 mb-2 font-display">Team Status</div>
                  <div className="text-sm text-ink-500 font-mono">{currentTime.toLocaleTimeString()}</div>
                </div>

                <div className="space-y-4">
                  <motion.div
                    className="flex items-center justify-between p-3 bg-emerald-50 rounded-xl"
                    whileHover={{ scale: 1.03, rotateX: 4 }}
                    style={{ transformStyle: 'preserve-3d' }}
                  >
                    <div className="flex items-center">
                      <div className="w-3 h-3 bg-emerald-500 rounded-full mr-3 animate-pulse"></div>
                      <span className="font-medium text-emerald-800">Work Available</span>
                    </div>
                    <span className="font-bold text-emerald-600"><Counter to={workAvailableCount || 1} /></span>
                  </motion.div>

                  <motion.div
                    className="flex items-center justify-between p-3 bg-purple-50 rounded-xl"
                    whileHover={{ scale: 1.03, rotateX: 4 }}
                    style={{ transformStyle: 'preserve-3d' }}
                  >
                    <div className="flex items-center">
                      <div className="w-3 h-3 bg-purple-500 rounded-full mr-3"></div>
                      <span className="font-medium text-purple-800">Personal Activities</span>
                    </div>
                    <span className="font-bold text-purple-600"><Counter to={personalActivityCount || 5} /></span>
                  </motion.div>

                  <motion.div
                    className="flex items-center justify-between p-3 bg-red-50 rounded-xl"
                    whileHover={{ scale: 1.03, rotateX: 4 }}
                    style={{ transformStyle: 'preserve-3d' }}
                  >
                    <div className="flex items-center">
                      <div className="w-3 h-3 bg-red-500 rounded-full mr-3"></div>
                      <span className="font-medium text-red-800">Work Meetings</span>
                    </div>
                    <span className="font-bold text-red-600"><Counter to={workMeetingCount || 1} /></span>
                  </motion.div>

                  <motion.div
                    className="mt-6 p-4 bg-gradient-to-r from-purple-600 to-fuchsia-600 rounded-xl text-white text-center depth-shadow"
                    animate={{ boxShadow: ['0 10px 30px rgba(147,51,234,0.25)', '0 10px 40px rgba(147,51,234,0.5)', '0 10px 30px rgba(147,51,234,0.25)'] }}
                    transition={{ duration: 3, repeat: Infinity }}
                  >
                    <div className="text-sm opacity-90">Team Productivity</div>
                    <div className="text-2xl font-bold font-display"><Counter to={94} suffix="%" /></div>
                    <div className="text-xs opacity-75">↑ 12% from yesterday</div>
                  </motion.div>
                </div>
              </div>
            </TiltCard>
          </div>

          {/* Live Team Members */}
          <div className="lg:col-span-2">
            <div className="grid gap-4">
              {activeUsers.map((user, index) => (
                <motion.div
                  key={user.id}
                  className="modern-card p-4 depth-shadow hover-lift group"
                  initial={{ opacity: 0, x: 40, rotateY: 12 }}
                  whileInView={{ opacity: 1, x: 0, rotateY: 0 }}
                  viewport={{ once: true, margin: '-40px' }}
                  transition={{ delay: index * 0.08, duration: 0.5 }}
                  style={{ transformStyle: 'preserve-3d' }}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3 sm:space-x-4 min-w-0">
                      <div className="relative">
                        <motion.div
                          className="w-12 h-12 bg-gradient-to-br from-purple-500 to-fuchsia-600 rounded-full flex items-center justify-center text-white font-bold"
                          whileHover={{ rotateY: 360 }}
                          transition={{ duration: 0.8 }}
                          style={{ transformStyle: 'preserve-3d' }}
                        >
                          {user.avatar}
                        </motion.div>
                        <div className={`absolute -bottom-1 -right-1 w-4 h-4 ${user.statusColor} rounded-full border-2 border-white ${user.status === 'online' ? 'animate-pulse' : ''}`}></div>
                      </div>

                      <div className="flex-1">
                        <div className="flex items-center space-x-2">
                          <h3 className="font-semibold text-ink-900">{user.name}</h3>
                          <span className="text-xs text-ink-500">• {user.location}</span>
                        </div>
                        <div className="text-sm text-ink-600">{user.role}</div>
                        <div className="flex items-center space-x-2 mt-1">
                          <user.activityIcon className="w-4 h-4 text-purple-400" />
                          <span className="text-sm text-ink-700">{user.activity}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center space-x-2 flex-shrink-0">
                      <div className="text-[10px] sm:text-xs text-ink-500 hidden xs:block sm:block">{user.lastSeen}</div>
                      <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button className="p-2 hover:bg-purple-50 rounded-full transition-colors">
                          <MessageCircle className="w-4 h-4 text-purple-600" />
                        </button>
                        <button className="p-2 hover:bg-purple-50 rounded-full transition-colors">
                          <Video className="w-4 h-4 text-purple-600" />
                        </button>
                      </div>
                    </div>
                  </div>

                  {user.status === 'online' && (
                    <div className="mt-3 flex items-center text-xs text-emerald-600">
                      <div className="w-2 h-2 bg-emerald-500 rounded-full mr-2 animate-ping"></div>
                      Active now
                    </div>
                  )}
                </motion.div>
              ))}
            </div>

            {/* Quick Actions */}
            <motion.div
              className="mt-6 sm:mt-8 p-4 sm:p-6 bg-white rounded-2xl depth-shadow border border-purple-100"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6 }}
            >
              <h3 className="font-semibold text-ink-900 mb-4 font-display">Quick Actions</h3>
              <div className="grid grid-cols-2 gap-2 sm:gap-3">
                {[
                  { icon: MessageCircle, label: 'Message All', bg: 'bg-purple-50 hover:bg-purple-100', text: 'text-purple-700' },
                  { icon: Video, label: 'Start Meeting', bg: 'bg-fuchsia-50 hover:bg-fuchsia-100', text: 'text-fuchsia-700' },
                  { icon: Calendar, label: 'Schedule', bg: 'bg-violet-50 hover:bg-violet-100', text: 'text-violet-700' },
                  { icon: Zap, label: 'Focus Mode', bg: 'bg-purple-50 hover:bg-purple-100', text: 'text-purple-700' },
                ].map((a) => (
                  <motion.button
                    key={a.label}
                    className={`flex items-center justify-center p-2.5 sm:p-3 ${a.bg} rounded-xl transition-colors`}
                    whileHover={{ scale: 1.05, rotateX: 8 }}
                    whileTap={{ scale: 0.97 }}
                    style={{ transformStyle: 'preserve-3d' }}
                  >
                    <a.icon className={`w-4 h-4 sm:w-5 sm:h-5 ${a.text} mr-1.5 sm:mr-2`} />
                    <span className={`text-xs sm:text-sm font-medium ${a.text}`}>{a.label}</span>
                  </motion.button>
                ))}
              </div>
            </motion.div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default LiveDashboardDemo;
