import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { ChapterHeading } from './motion-primitives';

const InteractiveDemoSection = () => {
  const [currentStory, setCurrentStory] = useState(0);

  const realStories = [
    {
      id: 1,
      name: 'Rajesh Kumar',
      age: 32,
      role: 'Software Engineer',
      emoji: '🚗',
      problem: 'Nearly crashed while answering calls during heavy traffic',
      solution: 'Sets "🚗 Driving" status. Family sees it and texts instead. Reaches home safely.',
      impact: 'Life saved. Zero distractions.',
      color: 'from-purple-600 to-fuchsia-600'
    },
    {
      id: 2,
      name: 'Priya Sharma',
      age: 28,
      role: 'Marketing Manager',
      emoji: '🏥',
      problem: 'Father had heart attack. Missed 15 calls in meeting. Saw them 2 hours later.',
      solution: 'Mother sends SOS. Emergency override breaks through silent mode. Priya responds in 30 seconds.',
      impact: 'Emergency handled. Father saved.',
      color: 'from-violet-600 to-purple-800'
    },
    {
      id: 3,
      name: 'Arjun Patel',
      age: 25,
      role: 'Student',
      emoji: '✈️',
      problem: 'Best friend visited after 5 years. Posted on Instagram. Arjun saw it 6 hours later. Friend had left.',
      solution: 'Friend updates status: "✈️ Just landed!". Arjun gets instant notification. They meet within 30 minutes.',
      impact: 'Reunion happened. Memories made.',
      color: 'from-fuchsia-500 to-purple-700'
    },
    {
      id: 4,
      name: 'Sarah Chen',
      age: 30,
      role: 'Designer',
      emoji: '📍',
      problem: "Missed spontaneous coffee meetup. Friend was 200m away but she didn't know.",
      solution: 'Gets notification: "Mike is 200m away at Starbucks!". Joins him in 5 minutes.',
      impact: 'Never miss nearby friends again.',
      color: 'from-purple-500 to-violet-700'
    },
    {
      id: 5,
      name: 'David Lee',
      age: 35,
      role: 'Team Lead',
      emoji: '💼',
      problem: 'Team constantly interrupted during focus time. Productivity dropped 40%.',
      solution: 'Everyone sets "🔴 Focus mode" status. Team respects it. Messages wait until free.',
      impact: 'Productivity up 60%. Team happier.',
      color: 'from-indigo-600 to-purple-800'
    }
  ];

  const nextStory = () => setCurrentStory((prev) => (prev + 1) % realStories.length);
  const prevStory = () => setCurrentStory((prev) => (prev - 1 + realStories.length) % realStories.length);

  useEffect(() => {
    const interval = setInterval(nextStory, 5000);
    return () => clearInterval(interval);
  }, []);

  const story = realStories[currentStory];

  return (
    <section className="section-padding bg-gradient-to-br from-purple-50 via-white to-purple-50 text-ink-900 relative overflow-hidden">
      <div className="orb orb-fuchsia w-[450px] h-[450px] bottom-0 -right-40 opacity-30"></div>
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <ChapterHeading
          chapter="Chapter 03 — Stories"
          title="Real Stories, Real Impact"
          subtitle="See how SyncUp is changing lives every day"
        />

        <div className="scene-3d-deep max-w-4xl mx-auto">
          <motion.div
            className="modern-card depth-shadow-lg p-4 sm:p-8 relative overflow-hidden"
            initial={{ rotateX: 12, opacity: 0, y: 60 }}
            whileInView={{ rotateX: 0, opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-80px' }}
            transition={{ duration: 0.8, ease: 'easeOut' }}
            style={{ transformStyle: 'preserve-3d' }}
          >
            <AnimatePresence mode="wait">
              <motion.div
                key={story.id}
                initial={{ opacity: 0, rotateY: 40, x: 80 }}
                animate={{ opacity: 1, rotateY: 0, x: 0 }}
                exit={{ opacity: 0, rotateY: -40, x: -80 }}
                transition={{ duration: 0.5, ease: 'easeOut' }}
                style={{ transformStyle: 'preserve-3d' }}
              >
                <div className={`bg-gradient-to-r ${story.color} rounded-2xl p-4 sm:p-8 text-white mb-4 sm:mb-6 depth-shadow`}>
                  <div className="text-center mb-4 sm:mb-6">
                    <motion.div
                      className="text-5xl sm:text-6xl mb-3 sm:mb-4 inline-block"
                      animate={{ y: [0, -10, 0], rotate: [0, 6, -6, 0] }}
                      transition={{ duration: 3, repeat: Infinity, ease: 'easeInOut' }}
                    >
                      {story.emoji}
                    </motion.div>
                    <h3 className="text-xl sm:text-2xl font-bold mb-2 font-display">{story.name}, {story.age}</h3>
                    <p className="text-white/90 font-medium">{story.role}</p>
                  </div>

                  <div className="space-y-3 sm:space-y-4">
                    <div className="bg-white/20 backdrop-blur-sm rounded-xl p-3 sm:p-4">
                      <div className="font-bold mb-1.5 sm:mb-2">❌ The Problem:</div>
                      <p className="text-xs sm:text-sm">{story.problem}</p>
                    </div>

                    <div className="bg-white/30 backdrop-blur-sm rounded-xl p-3 sm:p-4">
                      <div className="font-bold mb-1.5 sm:mb-2">✅ With SyncUp:</div>
                      <p className="text-xs sm:text-sm">{story.solution}</p>
                    </div>

                    <div className="bg-white/40 backdrop-blur-sm rounded-xl p-3 sm:p-4 text-center">
                      <div className="font-bold text-base sm:text-lg">{story.impact}</div>
                    </div>
                  </div>
                </div>
              </motion.div>
            </AnimatePresence>

            {/* Navigation */}
            <div className="flex items-center justify-between gap-2">
              <button
                onClick={prevStory}
                className="p-2.5 sm:p-3 bg-purple-50 hover:bg-purple-100 rounded-full transition-colors flex-shrink-0"
              >
                <ChevronLeft className="w-5 h-5 sm:w-6 sm:h-6 text-purple-700" />
              </button>

              <div className="flex gap-1.5 sm:gap-2">
                {realStories.map((_, index) => (
                  <button
                    key={index}
                    onClick={() => setCurrentStory(index)}
                    className={`h-2 rounded-full transition-all ${
                      index === currentStory ? 'w-6 sm:w-8 bg-purple-600' : 'w-2 bg-purple-200'
                    }`}
                  />
                ))}
              </div>

              <button
                onClick={nextStory}
                className="p-2.5 sm:p-3 bg-purple-50 hover:bg-purple-100 rounded-full transition-colors flex-shrink-0"
              >
                <ChevronRight className="w-5 h-5 sm:w-6 sm:h-6 text-purple-700" />
              </button>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default InteractiveDemoSection;
