import React from 'react';
import { motion } from 'framer-motion';
import { Download, Smartphone } from 'lucide-react';

const Footer = () => {
  return (
    <footer className="bg-ink-990 text-white py-16 relative overflow-hidden">
      <div className="aurora opacity-20"></div>
      <div className="orb orb-purple w-[400px] h-[400px] -bottom-40 left-1/4 opacity-20"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 sm:gap-8">
          <div>
            <div className="flex items-center space-x-2 mb-6">
              <motion.div
                className="w-8 h-8 rounded-lg overflow-hidden depth-shadow"
                whileHover={{ rotateY: 180 }}
                transition={{ type: 'spring', stiffness: 200 }}
                style={{ transformStyle: 'preserve-3d' }}
              >
                <img src="/logo.png" alt="Syncup logo" className="w-full h-full object-cover" />
              </motion.div>
              <span className="text-xl font-bold font-display gradient-text-light">Syncup</span>
            </div>
            <p className="text-purple-200/70 mb-2">
              Real-time status sharing, location intelligence, and seamless communication for modern life.
            </p>
            <p className="text-sm text-purple-300 font-medium mb-6">
              One Life, One Rhythm, One Sync
            </p>
            <div className="flex space-x-4">
              {['f', 't', 'in'].map((s) => (
                <motion.div
                  key={s}
                  className="w-10 h-10 bg-ink-800 rounded-lg flex items-center justify-center cursor-pointer"
                  whileHover={{ backgroundColor: '#a855f7', rotateX: 12, scale: 1.1, y: -3 }}
                  style={{ transformStyle: 'preserve-3d' }}
                >
                  <span className="text-sm font-bold">{s}</span>
                </motion.div>
              ))}
            </div>
          </div>
          <div>
            <h3 className="text-lg font-semibold mb-6 font-display">Product</h3>
            <ul className="space-y-3 text-purple-200/70">
              {['Features', 'How It Works', 'Pricing', 'Security'].map((l) => (
                <li key={l}>
                  <a href="#" className="hover:text-purple-300 transition-colors">{l}</a>
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h3 className="text-lg font-semibold mb-6 font-display">Support</h3>
            <ul className="space-y-3 text-purple-200/70">
              {['Help Center', 'Contact Us', 'Privacy Policy', 'Terms of Service'].map((l) => (
                <li key={l}>
                  <a href="#" className="hover:text-purple-300 transition-colors">{l}</a>
                </li>
              ))}
            </ul>
          </div>
          <div>
            <h3 className="text-lg font-semibold mb-6 font-display">Download</h3>
            <div className="space-y-3">
              {[
                { icon: Download, top: 'Download on the', name: 'App Store' },
                { icon: Smartphone, top: 'Get it on', name: 'Google Play' },
              ].map((b) => (
                <motion.button
                  key={b.name}
                  className="w-full bg-ink-800 px-4 py-3 rounded-lg flex items-center border border-purple-500/20"
                  whileHover={{ scale: 1.03, rotateX: 8, borderColor: 'rgba(168,85,247,0.6)' }}
                  whileTap={{ scale: 0.98 }}
                  style={{ transformStyle: 'preserve-3d' }}
                >
                  <b.icon className="w-5 h-5 mr-3 text-purple-400" />
                  <div className="text-left">
                    <div className="text-xs text-purple-200/60">{b.top}</div>
                    <div className="font-semibold">{b.name}</div>
                  </div>
                </motion.button>
              ))}
            </div>
          </div>
        </div>
        <div className="border-t border-purple-500/20 mt-10 sm:mt-12 pt-6 sm:pt-8">
          <div className="text-center mb-6 sm:mb-8">
            <motion.div
              className="inline-flex flex-col sm:flex-row items-center space-y-2 sm:space-y-0 sm:space-x-4 bg-gradient-to-r from-purple-600 to-fuchsia-600 text-white px-5 sm:px-6 py-3 rounded-2xl sm:rounded-full depth-shadow text-center"
              whileHover={{ scale: 1.04, rotateX: 6 }}
              animate={{ boxShadow: ['0 10px 30px rgba(147,51,234,0.3)', '0 10px 45px rgba(147,51,234,0.55)', '0 10px 30px rgba(147,51,234,0.3)'] }}
              transition={{ duration: 3, repeat: Infinity }}
              style={{ transformStyle: 'preserve-3d' }}
            >
              <Download className="w-5 h-5" />
              <span className="font-semibold">Download Syncup Now - It's Free!</span>
              <span className="bg-white text-purple-700 px-2 py-1 rounded-full text-xs font-bold">NEW</span>
            </motion.div>
          </div>
          <div className="text-center text-purple-200/60">
            <p className="mb-3">&copy; 2026 Syncup. All rights reserved. A product of Crackman Technologies. Built with ❤️ for better communication.</p>
            <p className="text-xs text-purple-200/40">
              🤖 AI-powered status suggestions • 🔒 End-to-end encrypted • 🌍 Available worldwide
            </p>
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
