import { useRef, useState, useEffect } from 'react';
import {
  motion,
  useScroll,
  useTransform,
  useSpring,
  useMotionValue,
} from 'framer-motion';

/* ============================================================
   SCROLL PROGRESS — gradient bar pinned to top of viewport
   ============================================================ */
export function ScrollProgress() {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, { stiffness: 120, damping: 30, restDelta: 0.001 });
  return <motion.div className="scroll-progress" style={{ scaleX }} />;
}

/* ============================================================
   PARALLAX — children drift vertically as the section scrolls past
   ============================================================ */
export function Parallax({ children, speed = 0.2, className = '' }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] });
  const y = useTransform(scrollYProgress, [0, 1], [`${speed * 100}%`, `${-speed * 100}%`]);
  return (
    <div ref={ref} className={className}>
      <motion.div style={{ y }}>{children}</motion.div>
    </div>
  );
}

/* ============================================================
   REVEAL — fade + rise on scroll into view
   ============================================================ */
export function Reveal({ children, delay = 0, y = 40, className = '' }) {
  return (
    <motion.div
      className={className}
      initial={{ opacity: 0, y }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: '-80px' }}
      transition={{ duration: 0.7, delay, ease: [0.22, 1, 0.36, 1] }}
    >
      {children}
    </motion.div>
  );
}

/* ============================================================
   REVEAL 3D — rotate in from below as it enters the viewport
   ============================================================ */
export function Reveal3D({ children, delay = 0, className = '' }) {
  return (
    <motion.div
      className={className}
      style={{ perspective: 1000 }}
      initial={{ opacity: 0, rotateX: -18, y: 60 }}
      whileInView={{ opacity: 1, rotateX: 0, y: 0 }}
      viewport={{ once: true, margin: '-80px' }}
      transition={{ duration: 0.8, delay, ease: [0.22, 1, 0.36, 1] }}
    >
      {children}
    </motion.div>
  );
}

/* ============================================================
   CHAPTER HEADING — story chapter label + title + subtitle
   ============================================================ */
export function ChapterHeading({ chapter, title, subtitle, dark = false, align = 'center' }) {
  const alignClass = align === 'left' ? 'text-left' : 'text-center';
  const mxClass = align === 'left' ? '' : 'mx-auto';
  return (
    <Reveal className={`mb-16 ${alignClass}`}>
      <span className={`chapter-label ${dark ? '!bg-purple-500/15 !text-purple-300 !border-purple-400/30' : ''} ${align === 'left' ? '' : 'mx-auto'}`}>
        {chapter}
      </span>
      <h2 className={`font-display text-3xl md:text-5xl lg:text-6xl font-bold mt-6 mb-4 text-hero ${dark ? 'text-white' : 'text-ink-900'}`}>
        {title}
      </h2>
      {subtitle && (
        <p className={`text-lg md:text-xl max-w-2xl ${mxClass} ${dark ? 'text-purple-200/80' : 'text-ink-500'}`}>
          {subtitle}
        </p>
      )}
    </Reveal>
  );
}

/* ============================================================
   TILT CARD — mouse-tilt 3D card (auto-disabled on touch)
   ============================================================ */
export function TiltCard({ children, className = '', max = 10 }) {
  const ref = useRef(null);
  const enabled = useRef(
    typeof window !== 'undefined' &&
      window.matchMedia('(hover: hover) and (pointer: fine)').matches
  );
  const handleMove = (e) => {
    if (!enabled.current) return;
    const el = ref.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const px = (e.clientX - rect.left) / rect.width - 0.5;
    const py = (e.clientY - rect.top) / rect.height - 0.5;
    el.style.transform = `rotateY(${px * max}deg) rotateX(${-py * max}deg) translateZ(8px)`;
  };
  const handleLeave = () => {
    if (ref.current) ref.current.style.transform = 'rotateY(0deg) rotateX(0deg) translateZ(0)';
  };
  return (
    <div className="scene-3d">
      <div ref={ref} onMouseMove={handleMove} onMouseLeave={handleLeave} className={`card-3d ${className}`}>
        {children}
      </div>
    </div>
  );
}

/* ============================================================
   SCROLL STAGE — a tall outer track with a sticky inner viewport.
   Exposes scrollYProgress (0→1 across the track) via a render prop,
   so children can drive any transform off the section's scroll.
   height = number of viewport heights the stage occupies.
   ============================================================ */
export function ScrollStage({ children, height = 200, className = '', innerClassName = '' }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start start', 'end end'] });
  return (
    <div ref={ref} className={className} style={{ height: `${height}vh` }}>
      <div className={`sticky-stage ${innerClassName}`}>{children(scrollYProgress)}</div>
    </div>
  );
}

/* ============================================================
   SCROLL ROTATE — wraps content and rotates it in 3D driven by
   the parent ScrollStage's progress. Used for the hero phone.
   ============================================================ */
export function ScrollRotate({ progress, rotate = [-18, 18], x = [0, 0], y = [0, 0], scale = [1, 1], opacity = [1, 1], className = '', children }) {
  const rotateY = useTransform(progress, [0, 1], rotate);
  const tx = useTransform(progress, [0, 1], x);
  const ty = useTransform(progress, [0, 1], y);
  const s = useTransform(progress, [0, 1], scale);
  const o = useTransform(progress, [0, 1], opacity);
  return (
    <motion.div className={className} style={{ rotateY, x: tx, y: ty, scale: s, opacity: o, transformStyle: 'preserve-3d' }}>
      {children}
    </motion.div>
  );
}

/* ============================================================
   TEXT REVEAL — splits a string into words and staggers them up
   into place as the block scrolls into view (Apple-style).
   ============================================================ */
export function TextReveal({ text, className = '', wordClassName = '', delay = 0, once = true }) {
  const words = text.split(' ');
  return (
    <span className={`text-reveal-wrap ${className}`}>
      {words.map((word, i) => (
        <span key={i} className="text-reveal-word">
          <motion.span
            className={`text-reveal-inner ${wordClassName}`}
            initial={{ y: '110%' }}
            whileInView={{ y: '0%' }}
            viewport={{ once, margin: '-60px' }}
            transition={{ duration: 0.8, delay: delay + i * 0.05, ease: [0.22, 1, 0.36, 1] }}
          >
            {word}
          </motion.span>
        </span>
      ))}
    </span>
  );
}

/* ============================================================
   MAGNETIC BUTTON — button that subtly follows the cursor.
   ============================================================ */
export function MagneticButton({ children, className = '', strength = 0.35, ...props }) {
  const ref = useRef(null);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const sx = useSpring(x, { stiffness: 200, damping: 15 });
  const sy = useSpring(y, { stiffness: 200, damping: 15 });
  const enabled = useRef(
    typeof window !== 'undefined' && window.matchMedia('(hover: hover) and (pointer: fine)').matches
  );
  const onMove = (e) => {
    if (!enabled.current || !ref.current) return;
    const r = ref.current.getBoundingClientRect();
    x.set((e.clientX - (r.left + r.width / 2)) * strength);
    y.set((e.clientY - (r.top + r.height / 2)) * strength);
  };
  const onLeave = () => { x.set(0); y.set(0); };
  return (
    <motion.button
      ref={ref}
      className={className}
      style={{ x: sx, y: sy }}
      onMouseMove={onMove}
      onMouseLeave={onLeave}
      {...props}
    >
      {children}
    </motion.button>
  );
}

/* ============================================================
   PARALLAX LAYER — depth layer that moves at a different rate
   than the foreground (for the cinematic stacked scenes).
   ============================================================ */
export function ParallaxLayer({ children, depth = 0.3, className = '' }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] });
  const y = useTransform(scrollYProgress, [0, 1], [`${depth * 100}%`, `${-depth * 100}%`]);
  return (
    <div ref={ref} className={className}>
      <motion.div style={{ y }}>{children}</motion.div>
    </div>
  );
}

/* ============================================================
   STICKY 3D — a sticky pinned element that rotates slightly as
   you scroll past it (great for product shots that "turn" in place).
   ============================================================ */
export function Sticky3D({ children, top = '20vh', rotate = [10, -10], scale = [1.05, 0.95], className = '' }) {
  const ref = useRef(null);
  const { scrollYProgress } = useScroll({ target: ref, offset: ['start end', 'end start'] });
  const rotateY = useTransform(scrollYProgress, [0, 1], rotate);
  const s = useTransform(scrollYProgress, [0, 0.5, 1], [scale[0], 1, scale[1]]);
  return (
    <div ref={ref} className={className} style={{ position: 'sticky', top }}>
      <motion.div style={{ rotateY, scale: s, transformStyle: 'preserve-3d' }}>{children}</motion.div>
    </div>
  );
}

/* ============================================================
   COUNTER — animates a number from 0 to value when in view.
   ============================================================ */
export function Counter({ to, suffix = '', duration = 1.6, className = '' }) {
  const ref = useRef(null);
  const [val, setVal] = useState(0);
  const started = useRef(false);
  useEffect(() => {
    if (!ref.current) return;
    const el = ref.current;
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !started.current) {
            started.current = true;
            const start = performance.now();
            const tick = (now) => {
              const p = Math.min((now - start) / (duration * 1000), 1);
              const eased = 1 - Math.pow(1 - p, 3);
              setVal(Math.round(eased * to));
              if (p < 1) requestAnimationFrame(tick);
            };
            requestAnimationFrame(tick);
          }
        });
      },
      { threshold: 0.4 }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [to, duration]);
  return (
    <span ref={ref} className={className}>
      {val}
      {suffix}
    </span>
  );
}
