import React, { useState, useEffect, useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import {
  Menu, X, Download, Smartphone, Clock, Users,
  MessageCircle, MapPin, Zap, Shield, Heart,
  Check, Building, TrendingUp, Globe, ArrowDown, Sparkles,
} from 'lucide-react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import ScenariosSection from './components/ScenariosSection';
import FeaturesSection from './components/FeaturesSection';
import InteractiveDemoSection from './components/InteractiveDemoSection';
import LiveDashboardDemo from './components/LiveDashboardDemo';
import AppShowcaseSection from './components/AppShowcaseSection';
import FAQSection from './components/FAQSection';
import Footer from './components/Footer';
import {
  ScrollProgress, Reveal, Reveal3D, ChapterHeading, TiltCard,
  ScrollStage, TextReveal, MagneticButton, Counter,
} from './components/motion-primitives';

function App() {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const heroRef = useRef(null);

  // Hero scroll-driven transforms (cinematic: layers peel + phone rotates as you scroll)
  const { scrollYProgress: heroProgress } = useScroll({
    target: heroRef,
    offset: ['start start', 'end start'],
  });
  const heroTextY = useTransform(heroProgress, [0, 1], ['0%', '70%']);
  const heroTextOpacity = useTransform(heroProgress, [0, 0.6], [1, 0]);
  const heroRotateX = useTransform(heroProgress, [0, 1], [0, 22]);
  const heroScale = useTransform(heroProgress, [0, 1], [1, 0.88]);
  const heroBgY = useTransform(heroProgress, [0, 1], ['0%', '35%']);
  const heroPhoneRotate = useTransform(heroProgress, [0, 1], [-12, 28]);
  const heroPhoneY = useTransform(heroProgress, [0, 1], ['0%', '-15%']);

  useEffect(() => {
    try {
      AOS.init({ duration: 800, easing: 'ease-out-cubic', once: true, offset: 100 });
    } catch (error) {
      console.warn('AOS initialization failed:', error);
    }

    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();

    const syncupText = 'Syncup';
    const taglineText = 'One Life, One Rhythm, One Sync';
    let syncupIndex = 0;
    let taglineIndex = 0;
    let syncupComplete = false;
    let animationTimeout;

    const typeSequential = () => {
      try {
        const syncupElement = document.getElementById('syncup-text');
        const taglineElement = document.getElementById('tagline-text');
        if (!syncupElement || !taglineElement) {
          animationTimeout = setTimeout(typeSequential, 100);
          return;
        }
        if (!syncupComplete) {
          if (syncupIndex <= syncupText.length) {
            syncupElement.textContent = syncupText.substring(0, syncupIndex);
            syncupIndex++;
            animationTimeout = setTimeout(typeSequential, Math.random() * 50 + 80);
          } else {
            syncupComplete = true;
            animationTimeout = setTimeout(typeSequential, 800);
          }
        } else if (taglineIndex <= taglineText.length) {
          taglineElement.textContent = taglineText.substring(0, taglineIndex);
          taglineIndex++;
          animationTimeout = setTimeout(typeSequential, Math.random() * 40 + 60);
        }
      } catch (error) {
        console.warn('Typing animation error:', error);
      }
    };

    const startTimeout = setTimeout(typeSequential, 1500);
    return () => {
      window.removeEventListener('scroll', onScroll);
      if (startTimeout) clearTimeout(startTimeout);
      if (animationTimeout) clearTimeout(animationTimeout);
    };
  }, []);

  return (
    <div id="app" className="min-h-screen bg-ink-990 text-white selection:bg-purple-500/30">
      <ScrollProgress />

      {/* ===== Navigation ===== */}
      <nav className={`fixed top-0 w-full nav-modern z-50 transition-all duration-300 ${scrolled ? 'scrolled' : ''}`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 rounded-xl overflow-hidden depth-shadow micro-bounce ring-1 ring-purple-400/30">
                <img src="/logo.png" alt="Syncup logo" className="w-full h-full object-cover" />
              </div>
              <div>
                <span className="text-lg sm:text-xl font-bold text-refined gradient-text-light font-display">Syncup</span>
                <div className="text-[10px] sm:text-xs text-purple-200/60 font-medium tracking-wide">One Life, One Rhythm, One Sync</div>
              </div>
            </div>
            <div className="hidden md:flex items-center space-x-8">
              <a href="#features" className="text-purple-100/80 hover:text-white transition-all duration-300 font-medium">Features</a>
              <a href="#how-it-works" className="text-purple-100/80 hover:text-white transition-all duration-300 font-medium">How It Works</a>
              <a href="#faq" className="text-purple-100/80 hover:text-white transition-all duration-300 font-medium">FAQ</a>
              <MagneticButton className="btn-primary btn-elegant !py-2.5 !px-6">Download Now</MagneticButton>
            </div>
            <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="md:hidden micro-bounce text-white">
              {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>
        {mobileMenuOpen && (
          <div className="md:hidden glass-dark border-t border-purple-500/20 px-4 py-4 space-y-3">
            <a href="#features" onClick={() => setMobileMenuOpen(false)} className="block text-purple-100 font-medium py-2">Features</a>
            <a href="#how-it-works" onClick={() => setMobileMenuOpen(false)} className="block text-purple-100 font-medium py-2">How It Works</a>
            <a href="#faq" onClick={() => setMobileMenuOpen(false)} className="block text-purple-100 font-medium py-2">FAQ</a>
            <button className="btn-primary w-full">Download Now</button>
          </div>
        )}
      </nav>

      {/* ===== HERO — Chapter 00: The Reveal (cinematic pinned) ===== */}
      <section ref={heroRef} className="relative min-h-screen overflow-hidden bg-ink-990">
        {/* Aurora + parallax ambient background */}
        <motion.div className="absolute inset-0" style={{ y: heroBgY }}>
          <div className="aurora opacity-70"></div>
          <div className="bg-grid-dark absolute inset-0"></div>
          <div className="orb orb-purple w-[600px] h-[600px] -top-40 -left-40 opacity-50"></div>
          <div className="orb orb-violet w-[500px] h-[500px] top-1/3 -right-32 opacity-40"></div>
          <div className="orb orb-fuchsia w-[360px] h-[360px] bottom-0 left-1/4 opacity-30"></div>
        </motion.div>
        <div className="grain"></div>

        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-24 sm:pt-28">
          <div className="grid lg:grid-cols-2 gap-8 sm:gap-12 items-center min-h-[85vh]">
            {/* Left: cinematic story text */}
            <motion.div style={{ y: heroTextY, opacity: heroTextOpacity, scale: heroScale }}>
              <Reveal>
                <div className="inline-flex items-center px-3 sm:px-4 py-2 glass-dark rounded-full text-xs sm:text-sm font-semibold mb-6 sm:mb-8 text-purple-200">
                  <Sparkles className="w-4 h-4 mr-2 text-purple-400" />
                  A product by Crackman Technologies
                </div>
              </Reveal>

              <h1 className="font-display text-5xl sm:text-6xl md:text-8xl font-extrabold text-white mb-4 sm:mb-6 text-cinematic">
                <TextReveal text="Sync Your" />
                <br />
                <span className="gradient-text"><TextReveal text="Entire Life" delay={0.2} /></span>
              </h1>

              <Reveal delay={0.35}>
                <p className="text-lg sm:text-xl md:text-2xl text-purple-100/70 mb-6 sm:mb-8 leading-relaxed max-w-2xl">
                  Real-time status sharing, location intelligence, and seamless communication that keeps you connected <span className="text-white font-semibold">and</span> protected.
                </p>
              </Reveal>

              <Reveal delay={0.5}>
                <div className="flex flex-col sm:flex-row gap-4 mb-8">
                  <MagneticButton className="btn-primary btn-elegant text-lg">
                    <Download className="w-5 h-5 mr-3" />
                    Download for iOS
                  </MagneticButton>
                  <MagneticButton className="btn-ghost-light text-lg">
                    <Smartphone className="w-5 h-5 mr-3" />
                    Get on Android
                  </MagneticButton>
                </div>
              </Reveal>

              <Reveal delay={0.65}>
                <div className="flex flex-wrap gap-6 text-sm text-purple-200/70">
                  <div className="flex items-center"><Check className="w-4 h-4 text-purple-400 mr-2" />Free forever plan</div>
                  <div className="flex items-center"><Check className="w-4 h-4 text-purple-400 mr-2" />No credit card required</div>
                  <div className="flex items-center"><Check className="w-4 h-4 text-purple-400 mr-2" />14-day premium trial</div>
                </div>
              </Reveal>
            </motion.div>

            {/* Right: 3D floating phone mockup with scroll rotation */}
            <div className="relative scene-3d-deep mt-4 lg:mt-0">
              <motion.div
                style={{ rotateY: heroPhoneRotate, rotateX: heroRotateX, y: heroPhoneY, transformStyle: 'preserve-3d' }}
                className="relative mx-auto w-[230px] sm:w-[290px] md:w-[330px]"
              >
                <div className="animate-float">
                  <div className="phone-frame phone-frame-glow relative aspect-[9/19]">
                    <div className="phone-notch"></div>
                    <div className="h-full bg-gradient-to-b from-purple-50 to-white pt-10 sm:pt-14 px-3 sm:px-4 pb-4">
                      <div className="text-center mb-3 sm:mb-4">
                        <div className="text-xl sm:text-2xl font-bold font-display gradient-text">
                          <span id="syncup-text"></span>
                        </div>
                        <div className="text-[10px] sm:text-xs font-medium text-ink-500 mt-1">
                          <span id="tagline-text"></span>
                        </div>
                      </div>
                      <div className="space-y-2 sm:space-y-3">
                        {[
                          { name: 'Sarah', status: '🎬 Watching movie — Until 10 PM', dist: '500m', color: 'bg-purple-500', bg: 'bg-purple-50 border-purple-100' },
                          { name: 'Mike', status: '☕ At Starbucks — Free to chat', dist: '200m', color: 'bg-fuchsia-500', bg: 'bg-fuchsia-50 border-fuchsia-100' },
                          { name: 'Raj', status: '🚗 Driving — Do not disturb', dist: '3km', color: 'bg-ink-800', bg: 'bg-ink-50 border-ink-100' },
                        ].map((f, i) => (
                          <div key={i} className={`rounded-2xl p-2 sm:p-3 border ${f.bg}`}>
                            <div className="flex items-center space-x-2 sm:space-x-3">
                              <div className={`w-8 h-8 sm:w-9 sm:h-9 ${f.color} rounded-full flex items-center justify-center text-white font-bold text-sm`}>{f.name[0]}</div>
                              <div className="flex-1 min-w-0">
                                <div className="font-semibold text-ink-900 text-sm">{f.name}</div>
                                <div className="text-xs text-ink-500 truncate">{f.status}</div>
                              </div>
                              <div className="text-xs text-purple-600 font-medium">{f.dist}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                      <div className="grid grid-cols-3 gap-1.5 sm:gap-2 mt-3 sm:mt-4">
                        {[['12', 'Online'], ['3', 'Nearby'], ['8', 'Stories']].map(([n, l]) => (
                          <div key={l} className="text-center p-1.5 sm:p-2 bg-white rounded-xl border border-purple-50">
                            <div className="text-base sm:text-lg font-bold text-purple-600">{n}</div>
                            <div className="text-[9px] sm:text-[10px] text-ink-500">{l}</div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Floating glass chips around the phone */}
                <motion.div
                  className="absolute -left-16 top-16 glass-dark rounded-2xl px-4 py-3 depth-shadow hidden md:block"
                  animate={{ y: [0, -10, 0] }}
                  transition={{ duration: 4, repeat: Infinity, ease: 'easeInOut' }}
                >
                  <div className="flex items-center gap-2">
                    <MapPin className="w-4 h-4 text-purple-400" />
                    <span className="text-sm font-semibold text-white">3 friends nearby</span>
                  </div>
                </motion.div>
                <motion.div
                  className="absolute -right-14 bottom-24 glass-dark rounded-2xl px-4 py-3 depth-shadow hidden md:block"
                  animate={{ y: [0, 12, 0] }}
                  transition={{ duration: 5, repeat: Infinity, ease: 'easeInOut', delay: 1 }}
                >
                  <div className="flex items-center gap-2">
                    <Zap className="w-4 h-4 text-fuchsia-400" />
                    <span className="text-sm font-semibold text-white">Live status</span>
                  </div>
                </motion.div>
              </motion.div>
            </div>
          </div>

          {/* Scroll indicator */}
          <motion.div
            className="flex flex-col items-center pb-10"
            style={{ opacity: heroTextOpacity }}
          >
            <span className="text-xs text-purple-300/70 tracking-widest uppercase mb-3">Scroll to begin the story</span>
            <div className="w-6 h-10 rounded-full border-2 border-purple-400/40 flex justify-center pt-2">
              <div className="w-1.5 h-1.5 rounded-full bg-purple-400 scroll-dot"></div>
            </div>
            <ArrowDown className="w-4 h-4 text-purple-400/50 mt-2" />
          </motion.div>
        </div>
      </section>

      {/* ===== PRODUCT REVEAL — pinned scroll stage, phone turns to reveal stats ===== */}
      <ScrollStage height={220} className="relative bg-ink-990">
        {(progress) => (
          <ProductRevealStage progress={progress} />
        )}
      </ScrollStage>

      <ScenariosSection />
      <InteractiveDemoSection />
      <LiveDashboardDemo />
      <AppShowcaseSection />
      <FeaturesSection />

      {/* ===== How It Works — story steps ===== */}
      <section id="how-it-works" className="section-padding bg-gradient-to-b from-ink-990 to-ink-950 relative overflow-hidden">
        <div className="orb orb-purple w-[500px] h-[500px] top-0 left-1/4 opacity-30"></div>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          <ChapterHeading
            dark
            chapter="Chapter 03 — Getting Started"
            title="Get Started in Minutes"
            subtitle="Four simple steps to revolutionize your communication"
          />
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-10">
            {[
              {
                icon: Download, title: 'Download & Set Up',
                description: 'Quick registration with phone verification',
                screen: (
                  <div className="flex flex-col items-center justify-center h-full gap-3">
                    <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-purple-500 to-purple-700 flex items-center justify-center depth-shadow">
                      <Download className="w-7 h-7 text-white" />
                    </div>
                    <div className="w-40 h-2.5 rounded-full bg-purple-100 overflow-hidden">
                      <motion.div
                        className="h-full bg-gradient-to-r from-purple-500 to-purple-700 rounded-full"
                        initial={{ width: '0%' }}
                        whileInView={{ width: '100%' }}
                        viewport={{ once: true }}
                        transition={{ duration: 1.6, delay: 0.4, ease: 'easeInOut' }}
                      />
                    </div>
                    <span className="text-[10px] text-ink-400 font-medium">Verifying number…</span>
                  </div>
                )
              },
              {
                icon: Users, title: 'Connect & Sync',
                description: 'Import contacts and build your network',
                screen: (
                  <div className="flex flex-col justify-center h-full gap-2 px-2">
                    {['Sarah', 'Mike', 'Raj'].map((n, i) => (
                      <motion.div
                        key={n}
                        className="flex items-center gap-2 bg-white rounded-xl p-2 border border-purple-100"
                        initial={{ opacity: 0, x: -20 }}
                        whileInView={{ opacity: 1, x: 0 }}
                        viewport={{ once: true }}
                        transition={{ delay: 0.4 + i * 0.25, duration: 0.5 }}
                      >
                        <div className="w-7 h-7 rounded-full bg-gradient-to-br from-purple-400 to-purple-600 flex items-center justify-center text-white text-xs font-bold">{n[0]}</div>
                        <span className="text-xs font-semibold text-ink-800">{n}</span>
                        <Check className="w-3.5 h-3.5 text-purple-500 ml-auto" />
                      </motion.div>
                    ))}
                  </div>
                )
              },
              {
                icon: MessageCircle, title: 'Share & Coordinate',
                description: 'Set statuses and share your location',
                screen: (
                  <div className="flex flex-col justify-center h-full gap-2 px-2">
                    <motion.div
                      className="bg-purple-600 text-white rounded-2xl rounded-bl-sm p-2.5 text-xs font-medium self-start"
                      initial={{ opacity: 0, scale: 0.6 }}
                      whileInView={{ opacity: 1, scale: 1 }}
                      viewport={{ once: true }}
                      transition={{ delay: 0.4, type: 'spring', stiffness: 200 }}
                    >
                      ☕ At Starbucks — Free to chat
                    </motion.div>
                    <motion.div
                      className="bg-white border border-purple-100 rounded-2xl rounded-br-sm p-2.5 text-xs text-ink-700 self-end flex items-center gap-1.5"
                      initial={{ opacity: 0, scale: 0.6 }}
                      whileInView={{ opacity: 1, scale: 1 }}
                      viewport={{ once: true }}
                      transition={{ delay: 0.8, type: 'spring', stiffness: 200 }}
                    >
                      <MapPin className="w-3.5 h-3.5 text-purple-500" /> Sharing live location
                    </motion.div>
                  </div>
                )
              },
              {
                icon: Heart, title: 'Stay In Sync',
                description: 'Enjoy effortless communication and coordination',
                screen: (
                  <div className="flex flex-col items-center justify-center h-full gap-3">
                    <motion.div
                      className="relative"
                      animate={{ scale: [1, 1.12, 1] }}
                      transition={{ duration: 2, repeat: Infinity, ease: 'easeInOut' }}
                    >
                      <div className="w-14 h-14 rounded-full bg-gradient-to-br from-fuchsia-500 to-purple-700 flex items-center justify-center depth-shadow">
                        <Heart className="w-7 h-7 text-white" />
                      </div>
                      {[0, 1].map((r) => (
                        <motion.span
                          key={r}
                          className="absolute inset-0 rounded-full border-2 border-purple-400"
                          animate={{ scale: [1, 1.8], opacity: [0.6, 0] }}
                          transition={{ duration: 2, repeat: Infinity, delay: r * 1 }}
                        />
                      ))}
                    </motion.div>
                    <div className="flex gap-1.5">
                      {['🎬', '🚗', '💼'].map((e, i) => (
                        <motion.span
                          key={e}
                          className="text-lg bg-white rounded-lg px-1.5 py-0.5 border border-purple-100"
                          animate={{ y: [0, -5, 0] }}
                          transition={{ duration: 2.4, repeat: Infinity, delay: i * 0.4 }}
                        >{e}</motion.span>
                      ))}
                    </div>
                  </div>
                )
              }
            ].map((step, index) => (
              <Reveal3D key={index} delay={index * 0.12}>
                <TiltCard className="h-full">
                  <div className="relative bg-white rounded-3xl p-6 border border-purple-100 depth-shadow hover-lift h-full flex flex-col items-center">
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2 w-9 h-9 bg-gradient-to-br from-purple-500 to-purple-700 rounded-full flex items-center justify-center text-white font-bold text-sm depth-shadow z-10">
                      {index + 1}
                    </div>

                    <div className="scene-3d my-4 sm:my-6">
                      <motion.div
                        className="phone-frame w-[120px] h-[170px] sm:w-[150px] sm:h-[210px] relative"
                        initial={{ rotateY: -24, rotateX: 8, scale: 0.9 }}
                        whileInView={{ rotateY: [-24, 24, -24], rotateX: 8, scale: 1 }}
                        viewport={{ once: false, margin: '-60px' }}
                        transition={{
                          rotateY: { duration: 8, repeat: Infinity, ease: 'easeInOut', delay: index * 0.5 },
                          scale: { duration: 0.6, delay: index * 0.12 },
                        }}
                        style={{ transformStyle: 'preserve-3d' }}
                      >
                        <div className="phone-notch !h-3.5 !w-14 sm:!h-4 sm:!w-16"></div>
                        <div className="h-full bg-gradient-to-b from-purple-50 to-white pt-7 sm:pt-8 px-2 pb-2">
                          {step.screen}
                        </div>
                      </motion.div>
                    </div>

                    <div className="flex items-center gap-2 mb-2">
                      <step.icon className="w-5 h-5 text-purple-600" />
                      <h3 className="text-lg font-semibold text-ink-900 font-display">{step.title}</h3>
                    </div>
                    <p className="text-ink-500 text-sm text-center">{step.description}</p>
                  </div>
                </TiltCard>
              </Reveal3D>
            ))}
          </div>
        </div>
      </section>

      {/* ===== Benefits ===== */}
      <section className="section-padding bg-white text-ink-900">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-16 items-center">
            <Reveal>
              <h2 className="font-display text-3xl md:text-5xl font-bold text-ink-900 mb-10 text-hero">
                Transform Your Daily Communication
              </h2>
              <div className="space-y-8">
                <div>
                  <h3 className="text-xl font-semibold text-ink-900 mb-4 flex items-center">
                    <Users className="w-6 h-6 text-purple-500 mr-3" />
                    For Individuals
                  </h3>
                  <ul className="space-y-3">
                    {[
                      'Never interrupt someone who\'s busy again',
                      'Get instant answers about availability',
                      'Maintain better work-life boundaries',
                      'Stay connected without being overwhelmed'
                    ].map((benefit, index) => (
                      <li key={index} className="flex items-start">
                        <Check className="w-5 h-5 text-purple-500 mr-3 mt-0.5 flex-shrink-0" />
                        <span className="text-ink-600">{benefit}</span>
                      </li>
                    ))}
                  </ul>
                </div>
                <div>
                  <h3 className="text-xl font-semibold text-ink-900 mb-4 flex items-center">
                    <Building className="w-6 h-6 text-purple-500 mr-3" />
                    For Teams
                  </h3>
                  <ul className="space-y-3">
                    {[
                      'Coordinate meetings effortlessly',
                      'Reduce unnecessary interruptions',
                      'Improve team communication',
                      'Boost overall productivity'
                    ].map((benefit, index) => (
                      <li key={index} className="flex items-start">
                        <Check className="w-5 h-5 text-purple-500 mr-3 mt-0.5 flex-shrink-0" />
                        <span className="text-ink-600">{benefit}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </Reveal>
            <Reveal3D>
              <TiltCard className="rounded-3xl">
                <div className="bg-gradient-to-br from-purple-600 to-purple-800 rounded-3xl p-8 text-white depth-shadow-lg">
                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="text-4xl font-bold font-display"><Counter to={85} suffix="%" /></div>
                        <div className="text-purple-200">Less Interruptions</div>
                      </div>
                      <TrendingUp className="w-8 h-8 text-purple-300" />
                    </div>
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="text-4xl font-bold font-display">2.5<span className="text-2xl">hrs</span></div>
                        <div className="text-purple-200">Time Saved Daily</div>
                      </div>
                      <Clock className="w-8 h-8 text-purple-300" />
                    </div>
                    <div className="flex items-center justify-between">
                      <div>
                        <div className="text-4xl font-bold font-display"><Counter to={98} suffix="%" /></div>
                        <div className="text-purple-200">User Satisfaction</div>
                      </div>
                      <Heart className="w-8 h-8 text-purple-300" />
                    </div>
                  </div>
                </div>
              </TiltCard>
            </Reveal3D>
          </div>
        </div>
      </section>

      {/* ===== Technology — dark story chapter ===== */}
      <section className="section-padding bg-ink-950 text-white relative overflow-hidden">
        <div className="aurora opacity-40"></div>
        <div className="orb orb-purple w-[500px] h-[500px] top-0 left-1/4 opacity-50"></div>
        <div className="orb orb-fuchsia w-[400px] h-[400px] bottom-0 right-0 opacity-40"></div>
        <div className="relative max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <ChapterHeading
            dark
            chapter="Chapter 04 — The Technology"
            title="Built with Cutting-Edge Technology"
            subtitle="Enterprise-grade security meets consumer-friendly design"
          />
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
            {[
              { icon: MapPin, title: 'Location Intelligence', description: 'Real-time location tracking with privacy-first design and beautiful 3D maps' },
              { icon: Zap, title: 'Real-Time Updates', description: 'WebSocket technology for instant status updates and notifications' },
              { icon: Globe, title: 'Cross-Platform', description: 'Available on iOS, Android, Web, Desktop, and Wearables' },
              { icon: Shield, title: 'Privacy & Security', description: 'End-to-end encryption, ghost mode, and granular privacy controls' }
            ].map((tech, i) => (
              <Reveal3D key={tech.title} delay={i * 0.12}>
                <div className="text-center p-6 rounded-2xl glass-dark hover-lift h-full">
                  <tech.icon className="w-12 h-12 text-purple-400 mx-auto mb-4" />
                  <h3 className="text-lg font-semibold mb-2 font-display">{tech.title}</h3>
                  <p className="text-purple-200/70 text-sm">{tech.description}</p>
                </div>
              </Reveal3D>
            ))}
          </div>
        </div>
      </section>

      <FAQSection />

      {/* ===== Final CTA ===== */}
      <section className="section-padding bg-gradient-to-r from-purple-600 via-purple-700 to-purple-800 text-white relative overflow-hidden">
        <div className="aurora opacity-30"></div>
        <div className="orb orb-fuchsia w-[400px] h-[400px] -top-20 right-10 opacity-60"></div>
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center relative">
          <Reveal>
            <h2 className="font-display text-3xl md:text-6xl font-bold mb-6 text-cinematic">
              Ready to Revolutionize Your Communication?
            </h2>
            <p className="text-xl text-purple-100 mb-2">
              Download Syncup today and experience the future of intelligent coordination
            </p>
            <p className="text-purple-300 font-medium mb-8">
              One Life, One Rhythm, One Sync
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <MagneticButton className="bg-white text-purple-700 px-8 py-4 rounded-full font-semibold hover:bg-purple-50 transition-colors">
                <Download className="w-5 h-5 mr-2 inline" />
                Download for iOS
              </MagneticButton>
              <MagneticButton className="bg-transparent border-2 border-white text-white px-8 py-4 rounded-full font-semibold hover:bg-white hover:text-purple-700 transition-colors">
                <Smartphone className="w-5 h-5 mr-2 inline" />
                Get on Android
              </MagneticButton>
            </div>
          </Reveal>
        </div>
      </section>

      <Footer />
    </div>
  );
}

/* ============================================================
   PRODUCT REVEAL STAGE — pinned scroll section.
   As you scroll, the phone rotates and three stat callouts
   rise into place around it (Apple-style product turntable).
   ============================================================ */
function ProductRevealStage({ progress }) {
  const phoneRotate = useTransform(progress, [0, 1], [-18, 24]);
  const phoneScale = useTransform(progress, [0, 0.5, 1], [0.9, 1, 0.95]);
  const phoneY = useTransform(progress, [0, 1], ['10%', '-10%']);

  const headingOpacity = useTransform(progress, [0, 0.15, 0.85, 1], [0, 1, 1, 0]);
  const headingY = useTransform(progress, [0, 0.15], [40, 0]);

  const stat1 = useTransform(progress, [0.15, 0.35], [0, 1]);
  const stat2 = useTransform(progress, [0.4, 0.6], [0, 1]);
  const stat3 = useTransform(progress, [0.65, 0.85], [0, 1]);

  return (
    <div className="relative w-full h-full flex items-center justify-center">
      <div className="aurora opacity-30"></div>
      <div className="bg-grid-dark absolute inset-0"></div>

      {/* Heading */}
      <motion.div
        className="absolute top-[14vh] left-0 right-0 text-center px-4"
        style={{ opacity: headingOpacity, y: headingY }}
      >
        <span className="chapter-label !bg-purple-500/15 !text-purple-300 !border-purple-400/30">
          Chapter 01 — The Product
        </span>
        <h2 className="font-display text-3xl md:text-5xl lg:text-6xl font-bold text-white mt-6 text-cinematic">
          One app. <span className="gradient-text">Your whole life.</span>
        </h2>
        <p className="text-lg md:text-xl text-purple-200/70 max-w-2xl mx-auto mt-4">
          Status, location, messaging, and coordination — perfectly in sync.
        </p>
      </motion.div>

      {/* Center phone turntable */}
      <motion.div
        style={{ rotateY: phoneRotate, scale: phoneScale, y: phoneY, transformStyle: 'preserve-3d' }}
        className="relative z-10"
      >
        <div className="phone-frame phone-frame-glow w-[230px] h-[460px] sm:w-[280px] sm:h-[560px] relative">
          <div className="phone-notch"></div>
          <div className="h-full bg-gradient-to-b from-purple-50 to-white pt-12 px-4 pb-4 overflow-hidden">
            <div className="text-center mb-4">
              <div className="text-2xl font-bold font-display gradient-text">Syncup</div>
              <div className="text-xs font-medium text-ink-500 mt-1">One Life, One Rhythm, One Sync</div>
            </div>
            <div className="space-y-2.5">
              {[
                { name: 'Sarah', status: '🎬 Movie — Until 10 PM', dist: '500m', color: 'bg-purple-500', bg: 'bg-purple-50 border-purple-100' },
                { name: 'Mike', status: '☕ Starbucks — Free', dist: '200m', color: 'bg-fuchsia-500', bg: 'bg-fuchsia-50 border-fuchsia-100' },
                { name: 'Priya', status: '🔴 Focus mode — 3 PM', dist: 'office', color: 'bg-ink-800', bg: 'bg-ink-50 border-ink-100' },
                { name: 'Raj', status: '🚗 Driving — DND', dist: '3km', color: 'bg-violet-500', bg: 'bg-violet-50 border-violet-100' },
              ].map((f, i) => (
                <div key={i} className={`rounded-2xl p-2.5 border ${f.bg}`}>
                  <div className="flex items-center space-x-2.5">
                    <div className={`w-8 h-8 ${f.color} rounded-full flex items-center justify-center text-white font-bold text-sm`}>{f.name[0]}</div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-ink-900 text-sm">{f.name}</div>
                      <div className="text-xs text-ink-500 truncate">{f.status}</div>
                    </div>
                    <div className="text-xs text-purple-600 font-medium">{f.dist}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </motion.div>

      {/* Floating stat callouts that rise in as you scroll */}
      <RevealStat style={{ opacity: stat1, x: -180, y: -40 }} className="left-[6%] sm:left-[12%] top-[42%]" icon={Zap} value="Sub-100ms" label="Real-time updates" />
      <RevealStat style={{ opacity: stat2, x: 180, y: 20 }} className="right-[6%] sm:right-[12%] top-[48%]" icon={Shield} value="End-to-end" label="Encrypted & private" />
      <RevealStat style={{ opacity: stat3, x: -160, y: 80 }} className="left-[10%] sm:left-[18%] bottom-[14%]" icon={Globe} value="5 platforms" label="iOS · Android · Web · Desktop · Watch" />
    </div>
  );
}

function RevealStat({ style, className = '', icon: Icon, value, label }) {
  return (
    <motion.div
      style={style}
      className={`absolute glass-dark rounded-2xl px-4 py-3 depth-shadow hidden sm:flex items-center gap-3 ${className}`}
    >
      <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-purple-500 to-fuchsia-600 flex items-center justify-center depth-shadow">
        <Icon className="w-5 h-5 text-white" />
      </div>
      <div>
        <div className="text-sm font-bold text-white font-display">{value}</div>
        <div className="text-xs text-purple-200/70">{label}</div>
      </div>
    </motion.div>
  );
}

export default App;
