import React from 'react';
import { motion } from 'framer-motion';
import { Clock, Coffee, Briefcase, Check, X } from 'lucide-react';
import { Reveal3D, TiltCard, ChapterHeading } from './motion-primitives';

const ScenariosSection = () => {
  const scenarios = [
    {
      id: 1,
      icon: Clock,
      title: 'Meeting Coordination',
      subtitle: 'Team scheduling made effortless',
      without: 'Send multiple messages, wait for replies, endless back-and-forth scheduling, 20 minutes wasted',
      with: "Check everyone's real-time status. See who's free instantly. Schedule meeting in 2 minutes.",
      timeSaved: '18 min',
      phone: (
        <div className="flex flex-col justify-center h-full gap-2 px-2">
          {[
            { n: 'Alex', s: '🟢 Free now', c: 'bg-emerald-500' },
            { n: 'Priya', s: '🔴 In meeting', c: 'bg-red-500' },
            { n: 'Sam', s: '🟢 Free now', c: 'bg-emerald-500' },
          ].map((u, i) => (
            <motion.div
              key={u.n}
              className="flex items-center gap-2 bg-white rounded-xl p-2 border border-purple-100"
              initial={{ opacity: 0, x: -16 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.4 + i * 0.25, duration: 0.5 }}
            >
              <div className={`w-6 h-6 ${u.c} rounded-full flex items-center justify-center text-white text-[10px] font-bold`}>{u.n[0]}</div>
              <span className="text-[10px] font-semibold text-ink-800">{u.s}</span>
            </motion.div>
          ))}
          <motion.div
            className="bg-purple-600 text-white rounded-xl p-2 text-[10px] font-semibold text-center"
            initial={{ opacity: 0, scale: 0.6 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 1.2, type: 'spring', stiffness: 200 }}
          >
            Meeting set ✓ 2 min
          </motion.div>
        </div>
      )
    },
    {
      id: 2,
      icon: Coffee,
      title: 'Social Plans',
      subtitle: 'Never interrupt friends again',
      without: 'Call at the wrong time, interrupt important moments, feel guilty, miss social opportunities',
      with: 'Check Sarah\'s status: "Free after 4 PM ☕". Send message. Plan coffee date instantly.',
      timeSaved: '15 min',
      phone: (
        <div className="flex flex-col justify-center h-full gap-2 px-2">
          <motion.div
            className="bg-white border border-purple-100 rounded-2xl rounded-bl-sm p-2.5 self-start"
            initial={{ opacity: 0, y: 12 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.4, duration: 0.5 }}
          >
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 bg-purple-500 rounded-full flex items-center justify-center text-white text-[10px] font-bold">S</div>
              <div>
                <div className="text-[10px] font-bold text-ink-900">Sarah</div>
                <div className="text-[10px] text-ink-500">☕ Free after 4 PM</div>
              </div>
            </div>
          </motion.div>
          <motion.div
            className="bg-purple-600 text-white rounded-2xl rounded-br-sm p-2.5 text-[10px] font-medium self-end"
            initial={{ opacity: 0, scale: 0.6 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 0.9, type: 'spring', stiffness: 200 }}
          >
            Coffee at 4? ☕
          </motion.div>
          <motion.div
            className="bg-white border border-purple-100 rounded-2xl rounded-bl-sm p-2.5 text-[10px] text-ink-700 self-start"
            initial={{ opacity: 0, scale: 0.6 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ delay: 1.3, type: 'spring', stiffness: 200 }}
          >
            Yes! See you there 🎉
          </motion.div>
        </div>
      )
    },
    {
      id: 3,
      icon: Briefcase,
      title: 'Work Collaboration',
      subtitle: 'Respect focus time',
      without: 'Interrupt focused work sessions, break concentration, reduce team productivity, create unnecessary stress',
      with: 'See John\'s status: "🔴 Focus mode until 3 PM". Wait until he\'s free. Respect his time.',
      timeSaved: '45 min',
      phone: (
        <div className="flex flex-col items-center justify-center h-full gap-3 px-2">
          <motion.div
            className="bg-ink-900 text-white rounded-2xl p-3 w-full text-center"
            initial={{ opacity: 0, rotateX: -30 }}
            whileInView={{ opacity: 1, rotateX: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.4, duration: 0.6 }}
            style={{ transformStyle: 'preserve-3d' }}
          >
            <div className="text-lg">🔴</div>
            <div className="text-[10px] font-bold">Focus mode</div>
            <div className="text-[9px] text-purple-300">until 3 PM</div>
          </motion.div>
          <motion.div
            className="flex items-center gap-1.5 bg-white border border-purple-100 rounded-xl p-2 w-full"
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 1, duration: 0.5 }}
          >
            <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
            <span className="text-[10px] text-ink-600 font-medium">Messages wait until free</span>
          </motion.div>
        </div>
      )
    }
  ];

  return (
    <section className="section-padding bg-gradient-to-b from-ink-950 via-ink-990 to-ink-950 text-white relative overflow-hidden">
      <div className="aurora opacity-25"></div>
      <div className="orb orb-purple w-[450px] h-[450px] top-20 -right-40 opacity-30"></div>
      <div className="orb orb-fuchsia w-[350px] h-[350px] bottom-10 -left-32 opacity-20"></div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
        <ChapterHeading
          dark
          chapter="Chapter 02 — Real Life"
          title="See Syncup in Action"
          subtitle="Real scenarios where Syncup saves time and keeps you perfectly synchronized"
        />

        <div className="grid lg:grid-cols-3 gap-6 sm:gap-10 mb-10 sm:mb-16">
          {scenarios.map((scenario, idx) => (
            <Reveal3D key={scenario.id} delay={idx * 0.15}>
              <TiltCard className="h-full">
                <div className="glass-dark rounded-3xl p-5 sm:p-6 depth-shadow hover-lift h-full flex flex-col">
                  <div className="flex items-center mb-4 sm:mb-5">
                    <div className="w-11 h-11 sm:w-12 sm:h-12 bg-gradient-to-br from-purple-500 to-purple-700 rounded-2xl flex items-center justify-center mr-3 sm:mr-4 depth-shadow flex-shrink-0">
                      <scenario.icon className="w-6 h-6 text-white" />
                    </div>
                    <div>
                      <h3 className="text-lg font-bold text-white text-refined font-display">{scenario.title}</h3>
                      <p className="text-sm text-purple-200/70 font-medium">{scenario.subtitle}</p>
                    </div>
                  </div>

                  {/* Mini phone mockup per scenario */}
                  <div className="scene-3d flex justify-center my-3 sm:my-4">
                    <motion.div
                      className="phone-frame phone-frame-glow w-[120px] h-[165px] sm:w-[140px] sm:h-[190px] relative"
                      initial={{ rotateY: -20, rotateX: 6, scale: 0.92 }}
                      whileInView={{ rotateY: [-20, 20, -20], rotateX: 6, scale: 1 }}
                      viewport={{ once: false, margin: '-60px' }}
                      transition={{
                        rotateY: { duration: 9, repeat: Infinity, ease: 'easeInOut', delay: idx * 0.6 },
                        scale: { duration: 0.6, delay: idx * 0.15 },
                      }}
                      style={{ transformStyle: 'preserve-3d' }}
                    >
                      <div className="phone-notch !h-3.5 !w-14 sm:!h-4 sm:!w-16"></div>
                      <div className="h-full bg-gradient-to-b from-purple-50 to-white pt-7 sm:pt-8 px-2 pb-2">
                        {scenario.phone}
                      </div>
                    </motion.div>
                  </div>

                  <div className="space-y-3 mt-auto">
                    <div className="bg-red-500/10 rounded-xl p-3 border-l-4 border-red-400/60">
                      <div className="text-xs font-semibold text-red-300 mb-1 flex items-center">
                        <X className="w-3.5 h-3.5 mr-1.5" /> Without Syncup
                      </div>
                      <p className="text-xs text-purple-100/70">{scenario.without}</p>
                    </div>

                    <div className="bg-emerald-500/10 rounded-xl p-3 border-l-4 border-emerald-400/60">
                      <div className="text-xs font-semibold text-emerald-300 mb-1 flex items-center">
                        <Check className="w-3.5 h-3.5 mr-1.5" /> With Syncup
                      </div>
                      <p className="text-xs text-purple-100/70">{scenario.with}</p>
                    </div>

                    <div className="bg-purple-500/10 rounded-xl p-3 border border-purple-400/20">
                      <div className="flex items-center justify-between">
                        <span className="text-xs font-semibold text-purple-200">Time Saved</span>
                        <span className="text-lg font-bold gradient-text font-display">{scenario.timeSaved}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </TiltCard>
            </Reveal3D>
          ))}
        </div>
      </div>
    </section>
  );
};

export default ScenariosSection;
